function bindCourseCtas(course) {
  if (typeof NovaAnalytics !== 'undefined' && typeof NovaAnalytics.trackCourseView === 'function') {
    NovaAnalytics.trackCourseView(course);
  } else if (typeof sendGA4Event === 'function') {
    sendGA4Event('view_course', {
      course_id: course.id,
      course_name: course.name,
      academy_id: course.academyId || course.academy || '',
      page_type: 'course_detail'
    });
  }
  window.currentCourse = course;
  const safeFee = '₹' + (course.price ? course.price.toLocaleString('en-IN') : '');
  const enrollBtn = document.querySelector('.btn-enroll-full');
  if (enrollBtn) {
    enrollBtn.onclick = () => {
      if (typeof openEnrollmentModal === 'function') {
        openEnrollmentModal(course.name, course.academy, course.duration, safeFee, course.id);
      } else if (typeof openConsultationPopup === 'function') {
        openConsultationPopup(course.name);
      }
    };
  }
  const demoBtn = document.querySelector('#btn-detail-book-demo');
  if (demoBtn) {
    const isDemoEligible = (typeof isCourseDemoEligible === 'function') ? isCourseDemoEligible(course) : true;
    if (!isDemoEligible) {
      demoBtn.style.display = 'none';
      const demoItem = document.getElementById('detail-demo-item');
      if (demoItem) demoItem.style.display = 'none';
    } else {
      demoBtn.style.display = '';
      demoBtn.onclick = () => {
        if (typeof openDemoModal === 'function') {
          openDemoModal({
            courseId: course.id,
            courseName: course.name,
            academyName: course.academy,
            academyId: course.academyId,
            sourceCta: 'course_detail_sidebar'
          });
        }
      };
    }
  }
  const consultBtn = document.querySelector('.btn-consult-full');
  if (consultBtn) {
    consultBtn.onclick = () => {
      if (typeof openCounsellingModal === 'function') {
        openCounsellingModal({
          courseId: course.id,
          courseName: course.name,
          academyName: course.academy,
          academyId: course.academyId,
          sourceCta: 'course_detail_sidebar'
        });
      } else if (typeof openConsultationPopup === 'function') {
        openConsultationPopup(course.name);
      }
    };
  }
  const mobileEnrollBtn = document.querySelector('#sticky-mobile-bar .btn-primary');
  if (mobileEnrollBtn) {
    mobileEnrollBtn.onclick = () => {
      if (typeof openEnrollmentModal === 'function') {
        openEnrollmentModal(course.name, course.academy, course.duration, safeFee, course.id);
      } else if (typeof openConsultationPopup === 'function') {
        openConsultationPopup(course.name);
      }
    };
  }
}
